  fillTimesheetDays(timesheetData = {}) {
    const updated = {
      ...timesheetData
    };
    for (let d = 1; d <= 31; d++) {
      const key = 'd' + d;
      if (!updated[key]) {
        updated[key] = {
          status: 'NA'
        };
      } else if (!updated[key].status) {
        updated[key].status = 'NA';
      }
    }
    return updated;
  }
  generateDaysForMonth(date) {
    const year = date.getFullYear();
    const month = date.getMonth();
    const daysCount = new Date(year, month + 1, 0).getDate();
    this.daysInMonth = Array.from({
      length: daysCount
    }, (_, i) => {
      const day = i + 1;
      const weekday = new Date(year, month, day).toLocaleDateString('en-US', {
        weekday: 'short'
      }); // Mon, Tue...
      return {
        dayNumber: day,
        dayName: weekday
      };
    });
  }
