  buildCalendarGrid(timesheetData) {
    const year = this.selectedMonth.getFullYear();
    const month = this.selectedMonth.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const daysInMonth = lastDay.getDate();
    let grid = [];
    let week = new Array(firstDay.getDay()).fill({});
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      const key = 'd' + day;
      const data = timesheetData[key];
      const dateObj = {
        day,
        date,
        isToday: this.isToday(date),
        isWeekend: date.getDay() === 0 || date.getDay() === 6,
        isHoliday: data?.status === 'H',
        attendance: data?.status || null,
        intime: data?.inTime || null,
        outtime: data?.outTime || null
      };
      week.push(dateObj);
      if (week.length === 7) {
        grid.push(week);
        week = [];
      }
    }
    // Push last week if not empty
    if (week.length > 0) {
      while (week.length < 7) week.push({});
      grid.push(week);
    }
    this.monthGrid = grid;
  }
  isToday(date) {
    const today = new Date();
    return date.getDate() === today.getDate() && date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear();
  }
  generateMonthGrid() {
    // Replace this with your real backend data. For demo: random codes and times.
    const month = this.selectedMonth.getMonth();
    const year = this.selectedMonth.getFullYear();
    const firstDayOfMonth = new Date(year, month, 1);
    const lastDayOfMonth = new Date(year, month + 1, 0);
    const firstDayWeekIdx = (firstDayOfMonth.getDay() + 6) % 7; // Monday=0
    const daysInMonth = lastDayOfMonth.getDate();
    const today = new Date();
    let grid = [];
    let week = [];
    const attendanceCodes = ['P', 'A', 'PT', 'RP', 'P', 'P', 'A'];
    const holidays = [13]; // Example: 13th is a holiday
    for (let i = 0; i < firstDayWeekIdx; ++i) {
      week.push({
        date: new Date(0),
        day: '',
        isToday: false,
        isWeekend: false,
        isHoliday: false
      });
    }
    for (let day = 1; day <= daysInMonth; ++day) {
      const date = new Date(year, month, day);
      const weekday = (date.getDay() + 6) % 7;
      const isWeekend = weekday >= 5;
      const isHoliday = holidays.includes(day);
      const isToday = today.getFullYear() === year && today.getMonth() === month && today.getDate() === day;
      // Demo data - replace with API lookup!
      let attendance = '';
      let intime = '',
        outtime = '';
      if (isHoliday) {
        attendance = 'H';
      } else {
        attendance = attendanceCodes[(day + 1) % attendanceCodes.length];
        intime = attendance === 'A' ? '' : '09:' + (10 + day % 50).toString().padStart(2, '0');
        outtime = attendance === 'A' ? '' : '18:' + (20 + day % 40).toString().padStart(2, '0');
      }
      week.push({
        date,
        day,
        isToday,
        isWeekend,
        isHoliday,
        attendance,
        intime,
        outtime
      });
      if (week.length === 7) {
        grid.push(week);
        week = [];
      }
    }
    if (week.length) {
      while (week.length < 7) {
        week.push({
          date: new Date(0),
          day: '',
          isToday: false,
          isWeekend: false,
          isHoliday: false
        });
      }
      grid.push(week);
    }
    this.monthGrid = grid;
  }
