    this.status = status;
    this.selectedDeptId = deptId ?? null;
    // Reset pagination
    this.page1 = 1;
    this.pageSize = 20;
    this.getTableData(status, this.month, this.year, this.selectedDeptId, isEmployeeRepeated);
