  onFinalFileSelected(event) {
    const file = event.target.files[0];
    this.fileError2 = '';
    this.previewUrl2 = null;
    this.fileType2 = null;
    if (!file) return;
    const allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
    const maxSize = 500 * 1024;
    if (!allowedTypes.includes(file.type)) {
      this.fileError2 = 'Only PDF, JPG, JPEG, PNG, XLS, and XLSX files are allowed.';
      return;
    }
    if (file.size > maxSize) {
      this.fileError2 = 'File size must be 500Kb or less.';
      return;
    }
    // Cleanup old URL
    if (this.rawObjectUrl2) {
      URL.revokeObjectURL(this.rawObjectUrl2);
    }
    const objectUrl = URL.createObjectURL(file);
    this.rawObjectUrl2 = objectUrl;
    if (file.type === 'application/pdf') {
      this.previewUrl2 = this.sanitizer.bypassSecurityTrustResourceUrl(objectUrl);
      this.fileType2 = 'pdf';
    } else if (file.type.startsWith('image/')) {
      this.previewUrl2 = this.sanitizer.bypassSecurityTrustResourceUrl(objectUrl);
      this.fileType2 = 'image';
    } else {
      // Excel
      this.fileType2 = 'excel';
    }
    this.selectedFile2 = file;
    this.fileName2 = file.name;
  }
