      this.timesheetObj.createdOn = moment__WEBPACK_IMPORTED_MODULE_3__(this.timesheetObj.createdOn).format(dateTimeFormat);
      this.timesheetObj.officeInTime = '';
      this.timesheetObj.officeOutTime = '';
      this.timesheetObj.totalWorkingOfficeHours = '';
