    this.projectList = [...new Map(this.allProjectsList.map(project => [project[key], project])).values()].filter(project => {
      if (project.clientId == activityObj.clientId) {
        project['displayTeam'] = `${project.projectName} | ${project.teamName}`;
        return {
          teamId: project.teamId,
          teamName: project.teamName,
          projectName: project.projectName,
          displayTeam: project.displayTeam
        };
      }
    });
