  /* View Timesheets */
  getAllMyTimesheetsByEmpId(template) {
    this.allMyTimesheets = [];
    if (this.endDate < this.startDate) {
      if (!this.validationService.validateNullUndefinedEmptyString(this.startDate)) {
        this.alertMessage = "Please enter Start Date !!";
        this.openAlertMod(template, this.alertMessage);
        return false;
      }
      if (!this.validationService.validateNullUndefinedEmptyString(this.endDate)) {
        this.alertMessage = "Please enter End Date !!";
        this.openAlertMod(template, this.alertMessage);
        return false;
      }
      //console.log("end date is small");
      this.endDate = '';
      this.startDate = '';
    } else {
      let timesheetObj = new src_app_models_timesheet__WEBPACK_IMPORTED_MODULE_8__.Timesheet();
      timesheetObj.empId = this.currentUser.empId;
      timesheetObj.startDate = this.startDate;
      timesheetObj.endDate = this.endDate;
      //console.log("getAllMyTimesheetsByEmpId :", timesheetObj);
      this.timesheetService.getAllMyTimesheetsByEmpId(timesheetObj).pipe((0,rxjs_operators__WEBPACK_IMPORTED_MODULE_19__.first)()).subscribe(response => {
        if (response.serviceStatus == "Success") {
          this.allMyTimesheets = response.serviceResponse;
          this.allMyTimesheets.forEach(timesheet => {
            timesheet.date = timesheet.date ? moment__WEBPACK_IMPORTED_MODULE_3__(timesheet.date).format(src_app_app_component__WEBPACK_IMPORTED_MODULE_5__.AppComponent.DATE_FORMAT) : null;
            timesheet.officeInTime = timesheet.officeInTime ? moment__WEBPACK_IMPORTED_MODULE_3__(timesheet.officeInTime).format(src_app_app_component__WEBPACK_IMPORTED_MODULE_5__.AppComponent.DATETIME_FORMAT) : null;
            timesheet.officeOutTime = timesheet.officeOutTime ? moment__WEBPACK_IMPORTED_MODULE_3__(timesheet.officeOutTime).format(src_app_app_component__WEBPACK_IMPORTED_MODULE_5__.AppComponent.DATETIME_FORMAT) : null;
            timesheet.createdOn = timesheet.createdOn ? moment__WEBPACK_IMPORTED_MODULE_3__(timesheet.createdOn).format(src_app_app_component__WEBPACK_IMPORTED_MODULE_5__.AppComponent.DATETIME_FORMAT) : null;
            timesheet.isNightShiftDisplay = timesheet.isNightShift == 'true' ? 'Night Shift' : 'Regular Shift';
          });
          //console.log("allMyTimesheets :", this.allMyTimesheets);
        } else {
          console.error(response.serviceResponse);
        }
      });
    }
  }
