  openDetailTable(appreciationType, mode) {
    this.selectedAppreciationType = appreciationType;
    this.selectedAppreciationMode = mode;
    const payload = {
      appreciationBy: this.currentUser.empId
    };
    const apiCall = mode === 'sent' ? this.appreciationService.appreciationSentByCurrentUser(payload) : this.appreciationService.appreciationReceivedByCurrentUser(payload);
    apiCall.subscribe({
      next: res => {
        if (res?.serviceStatus === 'Success') {
          const rawList = res.serviceResponse;
          // Filter by appreciation type
          const filtered = rawList.filter(item => item.appreciateType?.toLowerCase().trim() === appreciationType.toLowerCase().trim());
          // Group by employeeId and count
          const groupedMap = new Map();
          filtered.forEach(item => {
            const key = item.employmentIdAccToET;
            if (groupedMap.has(key)) {
              groupedMap.get(key).count += 1;
            } else {
              groupedMap.set(key, {
                employmentId: item.employmentIdAccToET,
                name: item.name,
                department: item.departmentName,
                count: 1
              });
            }
          });
          this.groupedData = Array.from(groupedMap.values());
          this.showDetailTable = true;
        } else {
          this.groupedData = [];
          this.showDetailTable = false;
        }
      },
      error: err => {
        console.error(err);
        this.groupedData = [];
        this.showDetailTable = false;
      }
    });
    console.log(this.groupedData);
  }
