  onSelectionChange(team, object) {
    if (!this.selectedMembers) {
      this.selectedMembers = [];
    }
    console.log("kmjhg", team);
    const existingTeamIndex = this.selectedMembers.findIndex(item => item.team.teamId === team.teamId);
    if (object.selected) {
      if (existingTeamIndex === -1) {
        this.selectedMembers.push({
          team,
          object: [object]
        });
      } else {
        const alreadyAdded = this.selectedMembers[existingTeamIndex].object.some(m => m.empId === object.empId);
        if (!alreadyAdded) {
          this.selectedMembers[existingTeamIndex].object.push(object);
        }
      }
      const historyExists = this.employeeSelectionHistory.some(entry => entry.teamId === team.teamId && entry.empId === object.empId);
      if (!historyExists) {
        const deselectedMember = {
          teamId: team.teamId,
          empId: object.empId,
          employeeTeamMapId: object.employeeTeamMapId
        };
        this.employeeSelectionHistory.push(deselectedMember);
      }
    } else {
      if (existingTeamIndex !== -1) {
        const memberIndex = this.selectedMembers[existingTeamIndex].object.findIndex(m => m.empId === object.empId);
        if (memberIndex !== -1) {
          this.selectedMembers[existingTeamIndex].object.splice(memberIndex, 1);
          if (this.selectedMembers[existingTeamIndex].object.length === 0) {
            this.selectedMembers.splice(existingTeamIndex, 1);
          }
        }
      }
      const historyIndex = this.employeeSelectionHistory.findIndex(entry => entry.teamId === team.teamId && entry.empId === object.empId);
      if (historyIndex !== -1) {
        this.employeeSelectionHistory.splice(historyIndex, 1);
      }
    }
    console.log("Selected Members:", this.selectedMembers);
    console.log("Employee Selection History:", this.employeeSelectionHistory);
  }
