  getDocsForPreview(docId) {
    this.timesheetService.getDocumentDataByDocId(docId).pipe((0,rxjs_operators__WEBPACK_IMPORTED_MODULE_30__.first)()).subscribe(response => {
      if (response.serviceStatus == "Success") {
        this.docData = response.serviceResponse.docData;
        this.mimeType = response.serviceResponse.docMimeType;
        // Excel → Download
        if (this.mimeType === 'application/vnd.ms-excel' || this.mimeType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') {
          const fileName = response.serviceResponse.docName || 'document.xlsx';
          this.downloadExcel(this.docData, this.mimeType, fileName);
        }
        // PDF / Image → Preview
        else {
          this.showPreview(this.docData, this.mimeType);
        }
      }
    });
  }
  showPreview(base64Data, mimeType) {
    const dataUrl = `data:${mimeType};base64,${base64Data}`;
    this.previewUrl = this.sanitizer.bypassSecurityTrustResourceUrl(dataUrl);
    if (mimeType === 'application/pdf') {
      this.fileType = 'pdf';
    } else if (mimeType.startsWith('image/')) {
      this.fileType = 'image';
    } else {
      this.fileType = '';
    }
    // Open modal
    this.modalRef2 = this.modalService.open(this.previewModal, {
      modalDialogClass: 'modal-lg'
    });
  }
