  getWeekDay(date) {
    let weekDay = '';
    let day = new Date(date).getDay();
    switch (day) {
      case 0:
        {
          weekDay = 'Sunday';
          break;
        }
      case 1:
        {
          weekDay = 'Monday';
          break;
        }
      case 2:
        {
          weekDay = 'Tuesday';
          break;
        }
      case 3:
        {
          weekDay = 'Wednesday';
          break;
        }
      case 4:
        {
          weekDay = 'Thursday';
          break;
        }
      case 5:
        {
          weekDay = 'Friday';
          break;
        }
      case 6:
        {
          weekDay = 'Saturday';
          break;
        }
      default:
        {
          weekDay = '';
          break;
        }
    }
    return weekDay;
  }
