      totaltimesheetDaysCount = moment__WEBPACK_IMPORTED_MODULE_3__(`${currentDate.getFullYear()}-${currentDate.getMonth()}`, "YYYY-MM").daysInMonth();
      fromDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
