  onFileSelected(event, template) {
    const input = event.target;
    if (input.files && input.files.length > 0) {
      const file = input.files[0];
      const allowedTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/bmp', 'image/webp', 'image/tiff', 'image/tif', 'image/svg+xml', 'application/postscript'];
      const allowedExtensions = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.tiff', '.tif', '.svg', '.eps'];
      const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();
      // Validate file type
      if (!allowedTypes.includes(file.type) && !allowedExtensions.includes(fileExtension)) {
        this.openAlertMod(template, 'Please select only PDF files, images or scanned copies.');
        input.value = '';
        this.selectedFileName = null;
        this.selectedFile = null;
        return;
      }
      if (file.size > this.maxFileSizeMB * 1024 * 1024) {
        this.openAlertMod(template, 'File size should not exceed 1 MB.');
        input.value = '';
        this.selectedFileName = null;
        this.selectedFile = null;
        return;
      }
      if (file.size === 0) {
        this.openAlertMod(template, 'Selected file is empty. Please choose a valid file.');
        input.value = '';
        this.selectedFileName = null;
        this.selectedFile = null;
        return;
      }
      this.selectedFileName = file.name;
      this.selectedFile = file;
      console.log("KYC Document - Valid file selected:", {
        name: this.selectedFileName,
        type: file.type,
        size: `${(file.size / 1024 / 1024).toFixed(2)} MB`,
        extension: fileExtension
      });
    } else {
      this.selectedFileName = null;
      this.selectedFile = null;
    }
  }
  getFileTypeDescription(file) {
    const extension = '.' + file.name.split('.').pop()?.toLowerCase();
    if (file.type === 'application/pdf' || extension === '.pdf') {
      return 'PDF Document';
    } else if (file.type.startsWith('image/')) {
      return 'Image File';
    } else {
      return 'Document';
    }
  }
