  getAppreciationEventSummaryInfo(appreciationEvent) {
    this.portalConfig = false;
    this.appreciationConfig = false;
    this.viewAppreciationForm = true;
    this.isAppreciationTable = false;
    this.isTable = false;
    this.viewEventConfig = false;
    this.isCreation = false;
    this.isUpdation = false;
    this.isHelpConfiguration = false;
    this.appreciationObj = appreciationEvent;
    //console.log("appreciationObj :",this.appreciationObj);
    this.portalService.getAppreciationEventSummaryInfo(this.appreciationObj).pipe((0,rxjs_operators__WEBPACK_IMPORTED_MODULE_20__.first)()).subscribe(response => {
      if (response.serviceStatus == "Success") {
        this.EventSummaryInfo = response.serviceResponse;
        //console.log("EventSummaryInfo :",this.EventSummaryInfo);
      } else {
        console.error(response.serviceResponse);
      }
    });
    this.portalService.getAllEmployeeAppreciationListByCategory(this.appreciationObj).pipe((0,rxjs_operators__WEBPACK_IMPORTED_MODULE_20__.first)()).subscribe(response => {
      if (response.serviceStatus == "Success") {
        this.EmployeeAppreciationList = response.serviceResponse;
        const sorted = [...this.EmployeeAppreciationList].sort((a, b) => Number(b.totalAppreciation ?? 0) - Number(a.totalAppreciation ?? 0));
        // Assign dense ranks (no skipping)
        let ranked = [];
        let currentRank = 1;
        let prevScore = null;
        for (let i = 0; i < sorted.length; i++) {
          const emp = sorted[i];
          const empScore = Number(emp.totalAppreciation ?? 0);
          if (prevScore === null || empScore !== prevScore) {
            currentRank = ranked.length === 0 ? 1 : ranked[ranked.length - 1].rank + 1;
          }
          ranked.push({
            ...emp,
            rank: currentRank
          });
          prevScore = empScore;
        }
        // Take top 7 only
        this.top7Appreciated = ranked.filter(e => e.rank <= 7);
        // Fix: Explicitly cast Set result to number[]
        const scores = Array.from(new Set(this.top7Appreciated.map(e => Number(e.totalAppreciation ?? 0))));
        // Sort scores descending
        scores.sort((a, b) => b - a);
        // Map score to background color
        this.appreciationColorMap = {};
        scores.forEach((score, idx) => {
          this.appreciationColorMap[score] = this.colorPalette[idx % this.colorPalette.length];
        });
      } else {
        console.error(response.serviceResponse);
      }
    });
  }
