  getVisibleColumns(allColumns) {
    if (!this.showExpandedColumns) {
      const primaryColumnKeys = ['employeementId', 'empId', 'name', 'email', 'departmentName', 'managerName', 'dateOfJoining', 'onRollDate', 'employmentstatus'];
      return allColumns.filter(column => primaryColumnKeys.some(key => column.key === key || column.sortKey === key));
    }
    return allColumns;
  }
  getColspanCount() {
    let baseColumns = 9;
    if (this.showExpandedColumns) {
      let expandedColumns = 0;
      if (this.isTable) {
        expandedColumns += 1;
        if (!this.isActiveTable) expandedColumns += 1;
        if (this.dateOfReleivingshow) expandedColumns += 1;
        expandedColumns += 6;
        expandedColumns += 2;
      }
      if (this.isDraftTable) {
        expandedColumns += 1;
      }
      baseColumns += expandedColumns;
    }
    return baseColumns;
  }
