    return history.filter(h => h?.actionDate).map(h => {
      const dt = new Date(h.actionDate);
      return {
        year: !isNaN(dt.getTime()) ? dt.getFullYear() : '—',
        actionDate: h.actionDate,
        status: h.status || 'Pending',
        financialYear: h.financialYear || '—',
        quarterCycle: h.quarterCycle || '—',
        raterName: h.name || '—',
        employeeName: targetEmployeeName,
        employeeId: targetEmployeeId,
        rating: h.rating || '—',
        feedback: h.feedback || '—'
      };
    }).sort((a, b) => new Date(b.actionDate).getTime() - new Date(a.actionDate).getTime());
